class Exercise {
  const Exercise(this.id, this.name, this.emoji, this.area, this.timed, this.amount, this.met, this.level, this.steps, this.tip, this.mistake, this.caution, this.muscles, this.breath);
  final String id, name, emoji, area, tip, mistake, caution, breath;
  final List<String> muscles;
  final bool timed; // true = detik, false = repetisi
  final int amount, level;
  final double met;
  final List<String> steps;
}

class WorkoutProgram {
  const WorkoutProgram(this.id, this.name, this.emoji, this.color, this.level, this.desc, this.rest, this.rounds, this.items);
  final String id, name, emoji, desc;
  final int color, level, rest, rounds;
  final List<(String, int)> items;
}

